float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 st) {
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 0.0;
    for (int i = 0; i < 5; i++) {
        value += amplitude * noise(st);
        st *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;

    vec2 p = uv * 8.0 - vec2(iTime * 0.2, iTime * 0.1);

    float fbm_val = fbm(p);

    vec3 col = 0.5 + 0.5 * cos(6.28318 * (vec3(fbm_val) + vec3(0.0, 0.33, 0.67)));

    col = mix(col, vec3(0.1, 0.4, 0.7), fbm_val * 0.5);
    col = mix(col, vec3(0.8, 0.3, 0.1), clamp(fbm_val * 2.0 - 1.0, 0.0, 1.0));

    float glow = 0.6 + 0.4 * sin(iTime * 1.5 + fbm_val * 10.0);
    col *= glow;

    float vignette = smoothstep(0.9, 0.3, length(uv - vec2(uv.x, 0.5)));
    col *= vignette;

    fragColor = vec4(col, 1.0);
}

