precision highp float;            // Set default precision for floats

#define MARCH_STEPS 60
#define MARCH_DIST_MAX 100.0
#define SURF_DIST_THR 0.01

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdUnion(float d1, float d2) {
    return min(d1, d2);
}

float sdSubtraction(float d1, float d2) {
    return max(-d1, d2);
}

float sdIntersection(float d1, float d2) {
    return max(d1, d2);
}

vec3 hash33(vec3 p) {
    p = fract(p * vec3(443.897, 443.145, 443.719));
    p += dot(p, p.yxz + 19.19);
    return fract(vec3(p.x * p.y, p.z * p.x, p.y * p.z));
}

float noise(vec3 p) {
    vec3 ip = floor(p);
    vec3 fp = fract(p);
    fp = fp * fp * (3.0 - 2.0 * fp);
    vec3 h = hash33(ip);
    float n = mix(mix(mix(h.x, h.y, fp.x), mix(h.z, h.x, fp.x), fp.y), mix(mix(h.y, h.z, fp.x), mix(h.x, h.y, fp.x), fp.y), fp.z);
    return n;
}

float fbm(vec3 p) {
    float f = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        f += amp * noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

float getVolumetricDensity(vec3 p) {
    float d = fbm(p * 0.5 + vec3(0.0, iTime * 0.1, 0.0)) * 2.0 - 0.5;
    d += fbm(p * 2.0 + vec3(0.0, iTime * 0.05, 0.0)) * 0.5;
    d = max(0.0, d - 0.1);
    return d * d * 0.5;
}

vec3 getCamPos(float time) {
    return vec3(sin(time * 0.1) * 20.0, 10.0 + sin(time * 0.05) * 5.0, cos(time * 0.1) * 20.0);
}

vec3 getCamLookAt(float time) {
    return vec3(0.0, 5.0, 0.0);
}

mat3 setCamera(vec3 ro, vec3 ta, float cr) {
    vec3 cw = normalize(ta - ro);
    vec3 cp = vec3(sin(cr), cos(cr), 0.0);
    vec3 cu = normalize(cross(cw, cp));
    vec3 cv = normalize(cross(cu, cw));
    return mat3(cu, cv, cw);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = getCamPos(iTime);
    vec3 ta = getCamLookAt(iTime);
    mat3 camMat = setCamera(ro, ta, 0.0);
    vec3 rd = camMat * normalize(vec3(uv, 1.5));

    vec3 sunDir = normalize(vec3(0.5, 0.5, -0.5));
    vec3 skyColor = vec3(0.3, 0.5, 0.8);
    vec3 cloudColor = vec3(0.9, 0.9, 0.9);

    float totalDensity = 0.0;
    vec3 totalColor = vec3(0.0);

    float t = 0.0;
    for (int i = 0; i < MARCH_STEPS; i++) {
        vec3 p = ro + rd * t;
        float density = getVolumetricDensity(p);

        if (density > 0.001) {
            float lightT = 0.0;
            for (int j = 0; j < 5; j++) {
                float shadowDensity = getVolumetricDensity(p + sunDir * lightT);
                lightT += 1.0;
                totalDensity += shadowDensity * 0.1;
            }

            vec3 currentCloudColor = mix(cloudColor, skyColor, pow(max(0.0, dot(normalize(p - ro), sunDir)), 2.0));
            vec3 finalCloudColor = mix(currentCloudColor, vec3(0.0), totalDensity * 0.1);

            totalColor += finalCloudColor * density * 0.1;
