    float noise1 = fbm(p * 3.0 + vec2(time * 1.5, time * 0.8), 5, 0.6, 2.0);
    float noise2 = fbm(p * 5.0 + vec2(time * -1.2, time * 1.0), 6, 0.5, 2.5);
    float noise3 = fbm(p * 8.0 + vec2(time * 0.7, time * -0.9), 4, 0.7, 1.8);

