    float finalNoise = mix(noise1, noise2, 0.6 + sin(time * 0.3) * 0.3);
    finalNoise = mix(finalNoise, noise3, 0.4 + cos(time * 0.2) * 0.2);

    // Create swirling patterns by distorting the coordinates based on noise
    vec2 swirlCoord = p;
    swirlCoord.x += smoothstep(0.0, 1.0, finalNoise) * 0.2 * sin(time);
    swirlCoord.y += smoothstep(0.0, 1.0, finalNoise) * 0.2 * cos(time);

