    vec3 waterColor = vec3(0.2, 0.4, 0.8); // Blue water
    vec3 cloudColor = vec3(0.9, 0.95, 1.0);

    vec2 planetPos = vec2(0.0, 0.0);
    float planetRadius = 0.5;
    float distToPlanet = length(uv - planetPos);

    if (distToPlanet < planetRadius) {
