            vec3 moonBaseColor = hsv2rgb(vec3(float(i) * 0.3 + 0.1, 0.8, 0.9)); // Vibrant moon colors
            vec3 moonCraterColor = moonBaseColor * 0.5;
            vec3 moonColor = mix(moonBaseColor, moonCraterColor, craterMask);

            // Moon lighting
