            vec3 normal = normalize(vec3(moonSurfaceUV, sqrt(max(0.0, 1.0 - dot(moonSurfaceUV, moonSurfaceUV)))));
            float diff = max(0.0, dot(normal, lightDir));
            moonColor *= (0.2 + 0.8 * diff);

            finalColor += moonColor;
        }
    }

    // Vignette
    float vignette = 1.0 - pow(length(uv), 1.5) * 0.5;
    finalColor *= vignette;

    fragColor = vec4(finalColor, 1.0);
