    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 centered_uv = uv - 0.5;
    centered_uv.x *= iResolution.x / iResolution.y;

    float time = iTime * 0.5;

    float drip_interval = 2.0;
    int num_drops = 3;

    float displacement = 0.0;
    float total_weight = 0.0;

    for (int i = 0; i < num_drops; ++i) {
        float drop_seed = float(i) * 0.33;

        vec2 drop_center = vec2(
            sin(time * 0.5 + drop_seed * 10.0) * 0.3 + sin(time * 0.3 + drop_seed * 5.0) * 0.2,
            cos(time * 0.6 + drop_seed * 12.0) * 0.3 + cos(time * 0.4 + drop_seed * 6.0) * 0.2
        );

        float drip_time_offset = floor(time / drip_interval + drop_seed * 10.0) * drip_interval;
        float current_drip_time = time - drip_time_offset;

        float drop_radius = 0.05;
        float pulse_phase = current_drip_time * 2.0;
        float pulse_decay = max(0.0, 1.0 - current_drip_time / drip_interval);
        float pulse_strength = sin(pulse_phase) * exp(-current_drip_time * 2.0) * pulse_decay;
        pulse_strength *= (cos(pulse_phase * 0.5) * 0.5 + 0.5); 

        float dist_to_drop = length(centered_uv - drop_center);
        float ripple_amount = smoothstep(drop_radius * 2.0, 0.0, dist_to_drop);

        float ripple_wave = cos(dist_to_drop * 30.0 - pulse_phase) * 0.5 + 0.5;
        ripple_wave *= smoothstep(0.0, 0.5, dist_to_drop / drop_radius);

        float drop_effect = ripple_amount * pulse_strength * ripple_wave * 0.1;

        displacement += drop_effect;
        total_weight += ripple_amount * pulse_decay;
    }

    displacement += sineNoise(centered_uv * 10.0) * 0.02;

    vec3 light_dir = normalize(vec3(0.5, 0.5, 1.0));
    float reflectivity = 0.8;

    vec3 base_color = vec3(0.0, 0.3, 0.5);
    vec3 deep_water_color = vec3(0.0, 0.2, 0.4);

    vec2 displaced_uv = centered_uv + displacement * 0.1;

    float depth = 0.5 + displacement * 2.0;
    vec3 surface_color = mix(base_color, deep_water_color, clamp(depth, 0.0, 1.0));

