    return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

float noise(vec2 p)
{
    const float K = 0.146437;
    vec2 i = floor(p + (p.x + p.y) * K);
    vec2 a = p - i + (i.x + i.y) * K;
    vec2 o = (a.x > a.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 b = a - o + K;
    vec2 c = a - 1.0 + 2.0 * K;

    vec4 h = max(0.0, 0.5 - vec4(dot(a, a), dot(b, b), dot(c, c), dot(o, o)));
    vec4 n = h * h * h * h * vec4(dot(a, hash(i + vec2(0.0, 0.0))), dot(b, hash(i + o)), dot(c, hash(i + vec2(1.0, 1.0))), dot(o, hash(i + vec2(0.0, 0.0))));
    return dot(n, vec4(70.0));
}

float turbulence(vec2 p)
{
    float w = 0.0;
    float freq = 2.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++)
    {
