float hash12(vec2 p) {
    vec3 p3  = fract(p.xyx * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
    vec3 p3 = fract(p.xyx * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xy + p3.yz) * p3.zx);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv *= 5.0; // Scale the UVs for more cells

    vec2 p = floor(uv);
    vec2 f = fract(uv);

    float minDist = 8.0;
    vec3 color = vec3(0.0);

    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 neighbor = vec2(float(i), float(j));
            vec2 point = hash22(p + neighbor);

            // Animate points subtly
            point = 0.5 + 0.5 * sin(iTime * 0.5 + point * 6.28318);

            vec2 diff = neighbor + point - f;
            float dist = length(diff);

            if (dist < minDist) {
                minDist = dist;
            }
        }
    }

    // Beautiful color palette based on distance
    vec3 col = 0.5 + 0.5 * cos(iTime * 0.1 + minDist * 10.0 + vec3(0.0, 2.0, 4.0));
    col = mix(col, vec3(1.0, 0.7, 0.0), smoothstep(0.0, 0.1, minDist));
    col = mix(col, vec3(0.1, 0.0, 0.3), smoothstep(0.4, 0.5, minDist));
    col = mix(col, vec3(0.0, 0.5, 0.5), smoothstep(0.2, 0.3, minDist));

    // Emphasize cell borders
    col *= (1.0 - smoothstep(0.0, 0.05, minDist));

    fragColor = vec4(col, 1.0);
}

